#pragma mark Bypass Functions
    // Store orig imp to pointer
    static ssize_t (*orig_read)(int, void *, ssize_t);
    static int (*orig_open)(const char *, int, ...);
    static int (*orig_close)(int);
    static int target_fd = -1;
    
    // Custom Open Function
    int hacked_open(const char *path, int flags, ...) {
        // Check if this is the main binary
        if (path && (strstr(path, "/8 Ball Pool.app/8 Ball Pool") != NULL || 
                     strstr(path, "/pool") != NULL ||
                     strstr(path, "8 Ball Pool") != NULL)) {
            int fd = orig_open(path, flags);
            if (fd != -1) {
                target_fd = fd;
                NSLog(@"[dyldBypass] - Tracking binary fd: %d", fd);
            }
            return fd;
        }
        return orig_open(path, flags);
    }
    
    // Custom Close Function
    int hacked_close(int fd) {
        if (fd == target_fd) {
            target_fd = -1;
            swapLC = 0;
            swapCS = 0;
        }
        return orig_close(fd);
    }
    
    // Custom Read Function
    ssize_t hacked_read(int fildes, void *buf, ssize_t nbytes){
        // If reading from target binary
        if (fildes == target_fd) {
            // First read: 0x4000 bytes (4 pages)
            if (nbytes == 0x4000 && swapLC == 0) {
                NSLog(@"[dyldBypass] - Intercepting 0x4000 bytes read");
                memcpy(buf, lcData, 0x4000);
                swapLC += 1;
                return 0x4000;
            } 
            // Second read: 0x1000 bytes (1 page)
            else if (nbytes == 0x1000 && swapCS == 0) {
                NSLog(@"[dyldBypass] - Intercepting 0x1000 bytes read");
                memcpy(buf, csData, 0x1000);
                swapCS += 1;
                return 0x1000;
            }
        }
        return orig_read(fildes, buf, nbytes);
    }
    
#pragma mark Init Method
    +(void)init{
        NSLog(@"[dyldBypass] - Init dyldBypass");
        
        // Rebind symbols using fishhook
        struct rebinding rebindings[] = {
            {"open", (void *)hacked_open, (void **)&orig_open},
            {"read", (void *)hacked_read, (void **)&orig_read},
            {"close", (void *)hacked_close, (void **)&orig_close}
        };
        
        rebind_symbols(rebindings, 3);
        
        NSLog(@"[dyldBypass] - Bypass initialized successfully!");
    }

@end
